// Keep typed precision visible and reject unsupported volumes before billing.
function exactMilli(value){
  const text=String(value??'').trim();
  if(!/^\d{1,7}(?:\.\d{1,3})?$/.test(text))throw Error('Enter a fuel volume with at most 3 decimal places. Extra digits are not rounded.');
  const [whole,fraction='']=text.split('.');
  return Number(whole)*1000+Number(fraction.padEnd(3,'0'));
}
function integerLineTotal(quantity,rate){
  if(!Number.isSafeInteger(quantity)||quantity<0||quantity>1000000000||!Number.isSafeInteger(rate)||rate<0||rate>10000000)throw Error('Quantity or price exceeds the supported range.');
  return Number((BigInt(quantity)*BigInt(rate)+500n)/1000n);
}
async function downloadReportCsv(){
  const form=$('#report-form');if(!form||!form.reportValidity())return;
  await submit(form,async()=>{
    const data=Object.fromEntries(new FormData(form));
    if(data.from>data.to)throw Error('Select a valid date range.');
    const response=await fetch('api.php?'+new URLSearchParams({action:'report',format:'csv',...data}),{credentials:'same-origin'});
    if(!response.ok||!(response.headers.get('content-type')||'').includes('text/csv')){
      const result=await response.json().catch(()=>({}));throw Error(result.error||'Report could not be downloaded.');
    }
    const url=URL.createObjectURL(await response.blob()),link=document.createElement('a');
    link.href=url;link.download=`EFS-sales-${data.from}-${data.to}.csv`;document.body.append(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);
  });
}
